class Solution:
    def minTotalWait(self, P: int, dist: List[int], node: List[int], arrive: List[int]) -> int:
        from itertools import accumulate
        # A guard leaving at time s catches thief i iff s >= arrive[i] - pos[node[i]] =: a[i].
        # Sort a; each guard takes a contiguous block and leaves at its largest a.
        pos = [0, 0]
        for d in dist: pos.append(pos[-1] + d)
        a = sorted(t - pos[h] for h, t in zip(node, arrive)); m = len(a)
        if P >= m: return 0
        S = [0] + list(accumulate(a)); INF = float('inf')
        prev = [0] + [INF] * m
        for _ in range(P):
            cur = [0] + [INF] * m; hull = deque()      # lines y = -j*x + (prev[j] + S[j])
            for i in range(1, m + 1):
                j = i - 1
                if prev[j] < INF:
                    M, B = -j, prev[j] + S[j]
                    while len(hull) >= 2:
                        (m1, b1), (m2, b2) = hull[-2], hull[-1]
                        if (B - b1) * (m1 - m2) <= (b2 - b1) * (m1 - M): hull.pop()
                        else: break
                    hull.append((M, B))
                x = a[i - 1]
                while len(hull) >= 2 and hull[1][0] * x + hull[1][1] <= hull[0][0] * x + hull[0][1]:
                    hull.popleft()
                cur[i] = hull[0][0] * x + hull[0][1] + x * i - S[i]
            prev = cur
        return prev[m]

