class Solution {
public:
    long long minTotalWait(int P, vector<long long>& dist, vector<int>& node, vector<long long>& arrive) {
        typedef long long ll; typedef __int128 L;
        vector<ll> pos(dist.size() + 2, 0);
        for (size_t k = 0; k < dist.size(); k++) pos[k + 2] = pos[k + 1] + dist[k];
        int m = node.size(); vector<ll> a(m);
        for (int i = 0; i < m; i++) a[i] = arrive[i] - pos[node[i]];
        sort(a.begin(), a.end());
        if (P >= m) return 0;
        vector<ll> S(m + 1, 0); for (int i = 0; i < m; i++) S[i + 1] = S[i] + a[i];
        const ll INF = LLONG_MAX / 4; vector<ll> prev(m + 1, INF), cur(m + 1); prev[0] = 0;
        for (int k = 0; k < P; k++) {
            vector<pair<ll,ll>> h; size_t hd = 0; cur.assign(m + 1, INF); cur[0] = 0;
            for (int i = 1; i <= m; i++) {
                int j = i - 1;
                if (prev[j] < INF) {
                    ll M = -j, B = prev[j] + S[j];
                    while (h.size() - hd >= 2) {
                        auto [m1, b1] = h[h.size() - 2]; auto [m2, b2] = h.back();
                        if ((L)(B - b1) * (m1 - m2) <= (L)(b2 - b1) * (m1 - M)) h.pop_back(); else break;
                    }
                    h.push_back({M, B});
                    if (hd > h.size() - 1) hd = h.size() - 1;
                }
                ll x = a[i - 1];
                while (h.size() - hd >= 2 && (L)h[hd + 1].first * x + h[hd + 1].second <= (L)h[hd].first * x + h[hd].second) hd++;
                cur[i] = h[hd].first * x + h[hd].second + x * i - S[i];
            }
            swap(prev, cur);
        }
        return prev[m];
    }
};

